"use client";

import * as React from "react";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "@/lib/utils";

// Spinner: generated by UIX from the design system. Same variants and sizes as the Figma component.

const spinnerVariants = cva(
  "skin-quiet inline-block animate-spin rounded-full",
  {
    variants: {
      color: {
        brand: "border-brand-subtle border-t-brand border-r-brand",
        neutral: "border-muted border-t-fg-secondary border-r-fg-secondary",
        inverse: "border-inverse/30 border-t-fg-inverse border-r-fg-inverse",
      },
      size: {
        sm: "size-4 border-2",
        md: "size-6 border-[3px]",
        lg: "size-10 border-4",
      },
    },
    defaultVariants: {
      color: "brand",
      size: "md",
    },
  },
);

export interface SpinnerProps
  extends Omit<React.HTMLAttributes<HTMLSpanElement>, "color">,
    VariantProps<typeof spinnerVariants> {
  /** Accessible name. */
  label?: string;
}

const Spinner = React.forwardRef<HTMLSpanElement, SpinnerProps>(
  ({ className, color, size, label = "Loading", ...props }, ref) => (
    <span data-slot="spinner" data-kind="track" ref={ref} role="status" aria-label={label} className={cn(spinnerVariants({ color, size }), className)} {...props} />
  ),
);
Spinner.displayName = "Spinner";

export { Spinner, spinnerVariants };
